"""Condições comerciais registradas fora da planilha de taxas (fonte única).

A planilha é o que a Orbe conhece. Uma condição comercial (ex.: isenção da Casa do Estudante, R6)
muda a taxa contratada sem mudar a planilha. O motor usa a condição vigente quando houver e
compara a cobrança da Orbe com a planilha para separar falha da Orbe de falha da Tarvo (R16.1).
"""

from __future__ import annotations

import datetime as dt
import json
from dataclasses import dataclass
from decimal import Decimal
from pathlib import Path

CAMINHO_PADRAO = Path(__file__).resolve().parents[2] / "config" / "condicoes_comerciais.json"
COLUNAS_TAXA = ("debito", "credito_vista", "credito_2a6", "credito_7a12", "pix", "antecipacao")


@dataclass(frozen=True)
class Condicao:
    id: str
    cnpj: str
    taxas: dict[str, Decimal]
    inicio: dt.date
    fim: dt.date | None
    fonte: str
    aprovado_por: str
    descricao: str = ""

    def vale_em(self, data: dt.date) -> bool:
        return self.inicio <= data and (self.fim is None or data <= self.fim)


def _parse(item: dict) -> Condicao:
    taxas = {k: Decimal(str(v)) for k, v in item["taxas"].items()}
    desconhecidas = set(taxas) - set(COLUNAS_TAXA)
    if desconhecidas:
        raise ValueError(f"condição {item.get('id')}: modalidade desconhecida {sorted(desconhecidas)}")
    return Condicao(
        id=item["id"],
        cnpj=str(item["cnpj"]).zfill(14),
        taxas=taxas,
        inicio=dt.date.fromisoformat(item["inicio"]),
        fim=dt.date.fromisoformat(item["fim"]) if item.get("fim") else None,
        fonte=item["fonte"],
        aprovado_por=item["aprovado_por"],
        descricao=item.get("descricao", ""),
    )


def carregar(caminho: Path = CAMINHO_PADRAO) -> tuple[Condicao, ...]:
    """Lê o arquivo de condições. Arquivo ausente = nenhuma condição (não é erro)."""
    if not caminho.exists():
        return ()
    dados = json.loads(caminho.read_text(encoding="utf-8"))
    return tuple(_parse(item) for item in dados.get("condicoes", []))


def vigente(condicoes: tuple[Condicao, ...], cnpj: str, data: dt.date, coluna: str) -> Condicao | None:
    """Condição que define a taxa de `coluna` para o CNPJ na data, ou None."""
    candidatas = [c for c in condicoes if c.cnpj == cnpj and coluna in c.taxas and c.vale_em(data)]
    return max(candidatas, key=lambda c: c.inicio) if candidatas else None


@dataclass(frozen=True)
class SinalResolvido:
    """Texto da planilha já analisado (ex.: renegociação que já está na própria planilha)."""

    cnpj: str
    texto: str
    decisao: str
    fonte: str


def carregar_sinais_resolvidos(caminho: Path = CAMINHO_PADRAO) -> tuple[SinalResolvido, ...]:
    if not caminho.exists():
        return ()
    dados = json.loads(caminho.read_text(encoding="utf-8"))
    return tuple(
        SinalResolvido(str(i["cnpj"]).zfill(14), i["texto"].strip(), i["decisao"], i["fonte"])
        for i in dados.get("sinais_resolvidos", [])
    )


CAMPOS_OBRIGATORIOS = ("cnpj", "taxas", "inicio", "fonte", "aprovado_por")


def _validar_condicao(dados: dict) -> dict:
    """Valida na fronteira (tela/API). Taxas como fração em texto ("0.0199" = 1,99%)."""
    faltando = [c for c in CAMPOS_OBRIGATORIOS if not dados.get(c)]
    if "aprovado_por" in faltando:
        raise ValueError("informe quem aprovou a condição (R20: taxa e condição comercial = Comercial)")
    cnpj = "".join(ch for ch in str(dados.get("cnpj", "")) if ch.isdigit())
    if len(cnpj) != 14:
        raise ValueError(f"CNPJ precisa ter 14 dígitos (recebido: {dados.get('cnpj')!r})")
    taxas = dados.get("taxas") or {}
    if not taxas:
        raise ValueError("informe ao menos uma taxa por modalidade")
    desconhecidas = sorted(set(taxas) - set(COLUNAS_TAXA))
    if desconhecidas:
        raise ValueError(f"modalidade desconhecida: {desconhecidas}; use {list(COLUNAS_TAXA)}")
    normalizadas = {}
    for coluna, valor in taxas.items():
        taxa = Decimal(str(valor))
        if not Decimal("0") <= taxa < Decimal("1"):
            raise ValueError(f"taxa de {coluna} precisa estar entre 0 e 1 como fração (0.0199 = 1,99%)")
        normalizadas[coluna] = str(taxa)
    inicio = dt.date.fromisoformat(str(dados["inicio"]))
    fim = dt.date.fromisoformat(str(dados["fim"])) if dados.get("fim") else None
    if fim is not None and fim < inicio:
        raise ValueError("a data de fim não pode ser anterior ao início")
    if faltando:
        raise ValueError(f"campos obrigatórios faltando: {faltando}")
    return {
        "cnpj": cnpj,
        "lojista": dados.get("lojista", ""),
        "taxas": normalizadas,
        "inicio": inicio.isoformat(),
        "fim": fim.isoformat() if fim else None,
        "descricao": dados.get("descricao", ""),
        "fonte": dados["fonte"],
        "aprovado_por": dados["aprovado_por"],
        "registrado_por": dados.get("registrado_por") or "tela",
        "registrado_em": dt.date.today().isoformat(),
    }


def _ler_arquivo(caminho: Path) -> dict:
    if not caminho.exists():
        return {"condicoes": [], "sinais_resolvidos": []}
    return json.loads(caminho.read_text(encoding="utf-8"))


def _gravar_arquivo(caminho: Path, dados: dict) -> None:
    temporario = caminho.with_suffix(".tmp")
    temporario.write_text(json.dumps(dados, ensure_ascii=False, indent=2) + "\n", encoding="utf-8")
    temporario.replace(caminho)  # troca atômica: nunca deixa o arquivo pela metade


def registrar_condicao(caminho: Path, dados: dict) -> dict:
    """Acrescenta uma condição validada (não altera as existentes) e devolve o registro gravado."""
    nova = _validar_condicao(dados)
    atual = _ler_arquivo(caminho)
    existentes = atual.get("condicoes", [])
    numero = max((int(c["id"].split("-")[1]) for c in existentes), default=0) + 1
    registro = {"id": f"COND-{numero:04d}", **nova}
    _gravar_arquivo(caminho, {**atual, "condicoes": [*existentes, registro]})
    return registro


def registrar_sinal_resolvido(caminho: Path, dados: dict) -> dict:
    """Marca um texto da planilha como já analisado (não muda taxa) para não voltar como pendência."""
    cnpj = "".join(ch for ch in str(dados.get("cnpj", "")) if ch.isdigit())
    texto = str(dados.get("texto", "")).strip()
    if len(cnpj) != 14 or not texto or not dados.get("fonte"):
        raise ValueError("informe CNPJ (14 dígitos), o texto da planilha e a fonte da decisão")
    registro = {"cnpj": cnpj, "texto": texto, "decisao": dados.get("decisao") or "nao_muda_taxa",
                "fonte": dados["fonte"], "registrado_por": dados.get("registrado_por") or "tela",
                "registrado_em": dt.date.today().isoformat()}
    atual = _ler_arquivo(caminho)
    _gravar_arquivo(caminho, {**atual, "sinais_resolvidos": [*atual.get("sinais_resolvidos", []), registro]})
    return registro

"""Escrita dos arquivos de saida/ no formato fixo exigido pelo case.

CSV com ';', ponto decimal, datas AAAA-MM-DD, CNPJ só dígitos (14).
Valida igualdade exata (centavos) entre o valor da saída e a soma do rastro.
"""

from __future__ import annotations

import datetime as dt
from decimal import Decimal
from pathlib import Path

import pandas as pd

SCHEMAS: dict[str, list[str]] = {
    "comissoes_por_lojista.csv": ["id_saida", "cnpj", "lojista", "linha_negocio", "comissao_brl"],
    "divergencias_taxa.csv": ["id_saida", "cnpj", "linha_negocio", "ref_origem",
                              "taxa_contratada_pct", "taxa_aplicada_pct", "diferenca_brl"],
    "notas_a_emitir.csv": ["id_saida", "tomador_cnpj", "tomador", "linha_negocio", "valor_brl",
                           "discriminacao"],
    "lancamentos_classificados.csv": ["id_saida", "banco", "ref_origem", "data", "descricao", "valor",
                                      "conta_codigo", "metodo", "confianca"],
    "pendencias.csv": ["id_saida", "tipo", "ref_origem", "valor_brl", "motivo", "quem_decide"],
    "rastro.csv": ["id_saida", "arquivo_origem", "ref_origem", "valor"],
}
LINHAS_NEGOCIO = {"CHECKOUT", "REMESSA"}
BANCOS = {"AURORA", "MERIDIANO"}
METODOS = {"REGRA", "IA", "HUMANO"}


def _fmt(value: object) -> object:
    if isinstance(value, Decimal):
        return format(value, "f")
    if isinstance(value, (dt.date, dt.datetime)):
        return value.strftime("%Y-%m-%d")
    if value is None:
        return ""
    return value


def write_output(df: pd.DataFrame, filename: str, out_dir: Path) -> Path:
    """Valida colunas obrigatórias e escreve. Colunas extras ficam depois das obrigatórias."""
    required = SCHEMAS[filename]
    if df.empty:
        formatted = pd.DataFrame(columns=required)
    else:
        missing = [c for c in required if c not in df.columns]
        if missing:
            raise ValueError(f"{filename}: faltam colunas obrigatórias {missing}")
        extras = [c for c in df.columns if c not in required]
        formatted = df[required + extras].map(_fmt)
    out_dir.mkdir(parents=True, exist_ok=True)
    target = out_dir / filename
    formatted.to_csv(target, sep=";", index=False, encoding="utf-8")
    return target


def check_rastro(reported: pd.DataFrame, value_col: str, rastro: pd.DataFrame) -> pd.DataFrame:
    """Linhas de saída cuja soma do rastro não bate em centavos exatos.

    Rejeita diferenças de 0.01 e saídas sem origem (inclusive quando valor = 0).
    Reporta também id_saida inexistente no rastro.
    """
    if reported.empty:
        return reported
    sums = rastro.groupby("id_saida")["valor"].apply(lambda s: sum(s, Decimal(0)))
    merged = reported.assign(soma_rastro=reported["id_saida"].map(sums))
    merged["tem_rastro"] = reported["id_saida"].isin(set(rastro["id_saida"].unique()))
    merged["esperado"] = reported[value_col].apply(lambda v: v if isinstance(v, Decimal) else Decimal(str(v)))
    merged["bate"] = merged.apply(
        lambda r: r["tem_rastro"] and r["soma_rastro"] == r["esperado"], axis=1
    )
    return merged[~merged["bate"]]


def validate_rastro_integrity(rastro: pd.DataFrame, all_outputs_ids: set[str]) -> list[dict]:
    """Checagens globais do rastro:
    - id_saida em rastro deve existir em alguma saída.
    - Várias linhas de rastro com o mesmo id_saida são permitidas, mas rastro em id inexistente é erro.
    """
    problemas: list[dict] = []
    if rastro.empty:
        return problemas
    rastro_ids = set(rastro["id_saida"].unique())
    orfaos = rastro_ids - all_outputs_ids
    if orfaos:
        problemas.append({"codigo": "RASTRO_ORFAO", "ids": sorted(orfaos)})
    return problemas


REF_ARQUIVO_AUSENTE = "arquivo ausente"


def validate_refs_origem(
    rastro: pd.DataFrame, refs_por_arquivo: dict[str, set[str]], ausentes: set[str]
) -> list[dict]:
    """Toda linha do rastro aponta para uma linha que existe no arquivo de origem carregado.

    Sem isso, a soma pode bater e o rastro ainda apontar para um CNPJ ou um rótulo, que não
    levam a nenhuma linha (case: "todo número da saída aponta para a linha de origem").
    Única exceção: pendência de frente bloqueada aponta o próprio arquivo ausente (R34).
    """
    if rastro.empty:
        return []
    invalidas: list[dict] = []
    for arquivo, ref, id_saida in zip(rastro["arquivo_origem"].astype(str), rastro["ref_origem"].astype(str),
                                      rastro["id_saida"], strict=True):
        if arquivo in refs_por_arquivo:
            if ref not in refs_por_arquivo[arquivo]:
                invalidas.append({"id_saida": id_saida, "arquivo_origem": arquivo, "ref_origem": ref})
        elif not (ref == REF_ARQUIVO_AUSENTE and set(arquivo.split("|")) <= ausentes):
            invalidas.append({"id_saida": id_saida, "arquivo_origem": arquivo, "ref_origem": ref})
    if not invalidas:
        return []
    return [{"codigo": "REF_ORIGEM_INEXISTENTE", "qtd": len(invalidas), "exemplos": invalidas[:10]}]


def validate_cobertura_entradas(
    entradas: dict[str, set[str]], rastro: pd.DataFrame
) -> list[dict]:
    """Para cada ref_origem de cada arquivo de entrada, confirma que ela aparece em alguma linha
    de saída via rastro. Caso contrário é dado perdido: INPUT_SEM_SAIDA.

    `entradas` é um dict `{arquivo_origem: set[ref_origem]}` com as refs que o fechamento se
    comprometeu a tocar (ex.: todas as transações Orbe, todas as operações da Ponte).
    """
    problemas: list[dict] = []
    if not entradas:
        return problemas
    if rastro.empty:
        cobertos: dict[str, set[str]] = {k: set() for k in entradas}
    else:
        cobertos = {
            arq: set(rastro.loc[rastro["arquivo_origem"] == arq, "ref_origem"].astype(str).unique())
            for arq in entradas
        }
    for arq, esperadas in entradas.items():
        esperadas_str = {str(r) for r in esperadas}
        faltantes = sorted(esperadas_str - cobertos.get(arq, set()))
        if faltantes:
            problemas.append({"codigo": "INPUT_SEM_SAIDA", "arquivo_origem": arq, "refs": faltantes})
    return problemas

"""API do painel. Não tem regra de negócio: chama `run_closing`, lê a saída e grava condições
comerciais pelo módulo `tarvo.condicoes` (que valida). Valores monetários saem como texto."""

from __future__ import annotations

import datetime as dt
import fnmatch
import logging
import math
from decimal import Decimal
from pathlib import Path
from typing import Annotated, Any

import pandas as pd
from fastapi import FastAPI, File, HTTPException, UploadFile
from fastapi.responses import FileResponse
from fastapi.staticfiles import StaticFiles

from tarvo import condicoes as cond_mod
from tarvo import rules, sinais
from tarvo.avaliacao import avaliar_e_persistir
from tarvo.loaders import ESPERADOS, FILES, OPCIONAIS, load_disponiveis
from tarvo.loaders.identificar import classificar_lote
from tarvo.orquestrador import ClosingResult, run_closing

log = logging.getLogger("tarvo.web")
STATIC = Path(__file__).resolve().parent / "static"
FIXTURES = Path(__file__).resolve().parents[3] / "tests" / "fixtures"
LIMITE_UPLOAD = 20 * 1024 * 1024
PADROES_ACEITOS = [*FILES.values(), *OPCIONAIS.values(), "00_LEIA-ME*"]


def _json(valor: Any) -> Any:
    if isinstance(valor, Decimal):
        return str(valor)
    if isinstance(valor, dt.date):
        return valor.isoformat()
    if isinstance(valor, float) and math.isnan(valor):
        return None
    if valor is pd.NaT or valor is None:
        return None
    return valor


def _registros(df: pd.DataFrame) -> list[dict]:
    if df is None or df.empty:
        return []
    return [{k: _json(v) for k, v in linha.items()} for linha in df.to_dict("records")]


def _soma(df: pd.DataFrame, coluna: str, filtro=None) -> str:
    if df.empty:
        return "0.00"
    alvo = df[filtro(df)] if filtro is not None else df
    return str(sum((Decimal(str(v)) for v in alvo[coluna]), Decimal("0.00")))


def _totais(r: ClosingResult) -> dict:
    com, div = r.comissoes, r.divergencias

    def prefixo(p: str):
        return lambda d: d["id_saida"].str.startswith(p)

    return {
        "comissao_checkout": _soma(com, "comissao_brl", lambda d: d["linha_negocio"] == "CHECKOUT"),
        "comissao_remessa": _soma(com, "comissao_brl", lambda d: d["linha_negocio"] == "REMESSA"),
        "cobrar_orbe": _soma(div, "diferenca_brl", prefixo("CK-DIV")),
        "devolver_condicao": _soma(div, "diferenca_brl", prefixo("CK-COND")),
        "divergencia_remessa": _soma(div, "diferenca_brl", prefixo("RM-DIV")),
        "notas": _soma(r.notas, "valor_brl"),
    }


def _arquivos(dados: Path) -> list[dict]:
    achados = []
    for padrao in PADROES_ACEITOS:
        for f in sorted(dados.glob(padrao)):
            achados.append({"nome": f.name, "bytes": f.stat().st_size,
                            "opcional": any(fnmatch.fnmatch(f.name, p) for p in OPCIONAIS.values())})
    return achados


def criar_app(dados: Path, saida: Path, condicoes_path: Path | None = None) -> FastAPI:
    app = FastAPI(title="Tarvo · Fechamento", docs_url="/api/docs")
    app.state.dados = Path(dados)
    app.state.saida = Path(saida)
    app.state.condicoes = condicoes_path or cond_mod.CAMINHO_PADRAO
    app.state.resultado = None
    app.state.avaliacao = None

    def fechar() -> ClosingResult:
        try:
            r = run_closing(app.state.dados, app.state.saida, condicoes_path=app.state.condicoes)
        except (FileNotFoundError, ValueError, KeyError) as exc:
            log.exception("falha no fechamento")
            raise HTTPException(
                400, f"Não foi possível fechar com os arquivos de {app.state.dados}: {exc}"
            ) from exc
        app.state.resultado = r
        app.state.avaliacao = avaliar_e_persistir(r, fixtures_dir=FIXTURES, saida=app.state.saida) \
            if FIXTURES.exists() else None
        return r

    def resultado() -> ClosingResult:
        return app.state.resultado or fechar()

    def resposta(r: ClosingResult) -> dict:
        aval = (app.state.avaliacao or {}).get("resumo")
        return {
            "competencia": r.competencia,
            "execucao_id": r.execucao_id,
            "pasta_saida": str(r.out_dir),
            "regras_versao": rules.VERSION,
            "duracao_s": r.duracoes_s.get("total"),
            "arquivos": _arquivos(app.state.dados),
            "validacoes": {
                "rastro_ok": r.problemas_rastro.empty,
                "integridade_ok": not r.problemas_integridade,
                "problemas": [str(p) for p in r.problemas_integridade][:20],
                "referencia": aval,
            },
            "bloqueios": r.bloqueios,
            "totais": _totais(r),
            "tabelas": {nome: _registros(getattr(r, nome)) for nome in
                        ("comissoes", "divergencias", "notas", "lancamentos", "pendencias")},
        }

    @app.get("/api/fechamento")
    def get_fechamento() -> dict:
        return resposta(resultado())

    @app.post("/api/fechar")
    def post_fechar() -> dict:
        return resposta(fechar())

    @app.get("/api/rastro")
    def get_rastro_completo() -> dict:
        return {"linhas": _registros(resultado().rastro)}

    @app.get("/api/rastro/{id_saida}")
    def get_rastro(id_saida: str) -> dict:
        rastro = resultado().rastro
        linhas = rastro[rastro["id_saida"] == id_saida]
        if linhas.empty:
            raise HTTPException(404, f"Sem rastro para {id_saida}")
        return {"id_saida": id_saida, "linhas": _registros(linhas)}

    @app.get("/api/lojistas")
    def get_lojistas() -> list[dict]:
        taxas = load_disponiveis(app.state.dados)[0]["taxas"]
        if taxas is None:
            return []
        unicos = taxas.drop_duplicates("cnpj")[["cnpj", "lojista"]]
        return [{"cnpj": c, "lojista": str(n).strip()} for c, n in unicos.itertuples(index=False)]

    @app.get("/api/condicoes")
    def get_condicoes() -> dict:
        bruto = cond_mod._ler_arquivo(app.state.condicoes)
        return {"condicoes": bruto.get("condicoes", []),
                "sinais_resolvidos": bruto.get("sinais_resolvidos", [])}

    @app.post("/api/condicoes", status_code=201)
    def post_condicao(corpo: dict) -> dict:
        try:
            registro = cond_mod.registrar_condicao(app.state.condicoes, corpo)
        except (ValueError, TypeError) as exc:
            raise HTTPException(422, str(exc)) from exc
        return {"condicao": registro, "fechamento": resposta(fechar())}

    @app.post("/api/sinais-resolvidos", status_code=201)
    def post_sinal_resolvido(corpo: dict) -> dict:
        try:
            registro = cond_mod.registrar_sinal_resolvido(app.state.condicoes, corpo)
        except ValueError as exc:
            raise HTTPException(422, str(exc)) from exc
        return {"sinal": registro, "fechamento": resposta(fechar())}

    @app.get("/api/sinais")
    def get_sinais() -> list[dict]:
        r = resultado()
        taxas = load_disponiveis(app.state.dados)[0]["taxas"]
        if taxas is None:
            return []
        conds = cond_mod.carregar(app.state.condicoes)
        resolvidos = cond_mod.carregar_sinais_resolvidos(app.state.condicoes)
        return [{"id_saida": pid, "cnpj": m.sinal.cnpj, "lojista": m.sinal.lojista, "linha": m.sinal.linha,
                 "campo": m.sinal.campo, "texto": m.sinal.texto, "metodo": m.metodo}
                for m, pid in sinais.abertos(taxas, r.competencia, conds, resolvidos)]

    @app.get("/api/arquivos-esperados")
    def get_arquivos_esperados() -> list[dict]:
        return ESPERADOS

    async def _ler(arquivos: list[UploadFile]) -> list[tuple[str, bytes]]:
        lidos = []
        for a in arquivos:
            conteudo = await a.read()
            nome = Path(a.filename or "").name
            if len(conteudo) > LIMITE_UPLOAD:
                raise HTTPException(413, f"{nome} passa de 20 MB")
            lidos.append((nome, conteudo))
        return lidos

    @app.post("/api/arquivos/conferir")
    async def post_conferir(arquivos: Annotated[list[UploadFile], File()]) -> dict:
        """Só confere (não grava nem fecha): a tela mostra o que foi reconhecido e o que falta."""
        return classificar_lote(await _ler(arquivos))

    @app.post("/api/arquivos")
    async def post_arquivos(arquivos: Annotated[list[UploadFile], File()]) -> dict:
        lidos = await _ler(arquivos)
        lote = classificar_lote(lidos)
        if lote["problemas"]:
            raise HTTPException(422, "Arquivos com problema: " + "; ".join(lote["problemas"]))
        destino = app.state.saida / "entradas" / dt.datetime.now().strftime("%Y%m%d_%H%M%S")
        destino.mkdir(parents=True, exist_ok=True)
        canonicos = {i["nome"]: i["nome_canonico"] for i in lote["arquivos"]}
        for nome, conteudo in lidos:
            if canonicos.get(nome):
                (destino / canonicos[nome]).write_bytes(conteudo)
        app.state.dados = destino
        return resposta(fechar())

    if (STATIC / "index.html").exists():
        app.mount("/assets", StaticFiles(directory=STATIC / "assets"), name="assets")

        @app.get("/{caminho:path}", include_in_schema=False)
        def front(caminho: str) -> FileResponse:
            return FileResponse(STATIC / "index.html")

    return app

