import { useEffect, useMemo, useState } from "react";
import { api, type Caso, type CasoDetalhe, type Decisao, type Tratamento } from "../api";
import { dinheiro } from "../format";

interface Props {
  caso: Caso;
  pendencia: { id_saida: string | null; tipo: string | null; motivo: string | null; valor_brl: string | null };
  aoAtualizar: () => void;
}

/**
 * Fluxo compacto: lista decisões/precedentes do caso, permite registrar proposta,
 * aprovar/rejeitar/revogar segundo o perfil, e registrar resultado operacional.
 * Preserva o visual existente (mesmas classes utilitárias do Tailwind).
 */
export function FluxoDecisao({ caso, pendencia, aoAtualizar }: Props) {
  const [detalhe, setDetalhe] = useState<CasoDetalhe | null>(null);
  const [precedentes, setPrecedentes] = useState<Decisao[]>([]);
  const [acoes, setAcoes] = useState<Tratamento[]>([]);
  const [erro, setErro] = useState<string | null>(null);
  const [mensagem, setMensagem] = useState<string | null>(null);
  const [abrirForm, setAbrirForm] = useState(false);

  async function recarregar() {
    const [d, p, t] = await Promise.all([
      api.caso(caso.caso_hash),
      api.precedentes(caso.caso_hash).catch(() => ({ precedentes: [] })),
      api.tratamentos(),
    ]);
    setDetalhe(d);
    setPrecedentes(p.precedentes);
    setAcoes(t.acoes);
  }

  useEffect(() => {
    recarregar().catch((e) => setErro((e as Error).message));
    // eslint-disable-next-line react-hooks/exhaustive-deps
  }, [caso.caso_hash]);

  const acoesCompat = useMemo(() => {
    const tipo = pendencia.tipo ?? "";
    return acoes.filter(
      (a) => a.tipos_pendencia.includes(tipo) || (a.apenas_operacional && a.tipos_pendencia.length === 0)
    );
  }, [acoes, pendencia.tipo]);

  const pendente = detalhe?.decisoes.find((d) => d.status === "PENDENTE") ?? null;
  const aprovada = detalhe?.decisoes.find((d) => d.status === "APROVADA") ?? null;
  const resultado = detalhe?.resultados[0] ?? null;

  async function tratar<T>(acao: () => Promise<T>, msg: string) {
    try {
      await acao();
      setMensagem(msg);
      await recarregar();
      aoAtualizar();
    } catch (e) {
      setErro((e as Error).message);
    }
  }

  return (
    <div className="mt-4 rounded-md border border-linha bg-folha/50 p-3 text-sm">
      <h3 className="mb-2 text-xs font-semibold uppercase tracking-wider text-tinta-3">Ciclo de decisão</h3>
      {erro && <p className="mb-2 text-xs text-erro">{erro}</p>}
      {mensagem && <p className="mb-2 text-xs text-tinta-2">{mensagem}</p>}

      <HistoricoDecisoes decisoes={detalhe?.decisoes ?? []} />

      {aprovada && (
        <div className="mt-2 rounded border border-decisao/50 bg-decisao-fundo p-2 text-xs">
          <p>
            <strong>Tratamento aplicado:</strong> {aprovada.acao_tipo} ·
            aprovado por <strong>{aprovada.aprovador}</strong>
            {aprovada.aprovacao_externa?.aprovador && (
              <> (externamente: {aprovada.aprovacao_externa.aprovador})</>
            )}
          </p>
          <button
            onClick={() =>
              tratar(() => api.revogar(aprovada.id, "revogada pelo painel"), "Decisão revogada.")
            }
            className="mt-1 rounded border border-linha-forte px-2 py-0.5 text-xs hover:bg-papel"
          >
            Revogar
          </button>
        </div>
      )}

      {pendente && (
        <div className="mt-2 rounded border border-linha-forte bg-papel p-2 text-xs">
          <p>
            Proposta <strong>#{pendente.id}</strong> ({pendente.acao_tipo}) aguardando aprovação.
            Autor: {pendente.autor}.
          </p>
          <AprovarInline
            decisao={pendente}
            aoAprovar={(externa) =>
              tratar(
                () => api.aprovar(pendente.id, externa ? { aprovacao_externa: externa } : {}),
                "Decisão aprovada e aplicada."
              )
            }
            aoRejeitar={(motivo) => tratar(() => api.rejeitar(pendente.id, motivo), "Proposta rejeitada.")}
          />
        </div>
      )}

      {!pendente && !aprovada && (
        <button
          onClick={() => setAbrirForm((v) => !v)}
          className="mt-2 rounded border border-linha-forte px-2 py-1 text-xs hover:bg-papel"
        >
          {abrirForm ? "Fechar formulário" : "Registrar proposta de tratamento"}
        </button>
      )}

      {abrirForm && !pendente && !aprovada && (
        <PropostaForm
          caso={caso}
          pendencia={pendencia}
          acoesCompat={acoesCompat}
          aoProposto={() => {
            setAbrirForm(false);
            tratar(() => Promise.resolve(null), "Proposta registrada. Falta aprovação.");
          }}
        />
      )}

      <ResultadoOperacionalForm caso={caso} atual={resultado} aoAtualizar={() => tratar(() => Promise.resolve(null), "Resultado atualizado.")} />

      {precedentes.length > 0 && (
        <details className="mt-3">
          <summary className="cursor-pointer text-xs text-tinta-3 hover:text-tinta">
            Precedentes (não autorizam, só referência) · {precedentes.length}
          </summary>
          <ul className="mt-1 space-y-1 text-xs">
            {precedentes.map((p) => (
              <li key={p.id} className="rounded border border-linha-forte/60 bg-papel px-2 py-1">
                <span className="font-mono">{p.acao_tipo}</span> · {p.justificativa}
                <span className="ml-2 text-tinta-3">({p.status})</span>
              </li>
            ))}
          </ul>
        </details>
      )}
    </div>
  );
}

function HistoricoDecisoes({ decisoes }: { decisoes: Decisao[] }) {
  if (!decisoes.length) return <p className="text-xs text-tinta-3">Nenhuma decisão registrada ainda.</p>;
  return (
    <ul className="space-y-1 text-xs">
      {decisoes.map((d) => (
        <li key={d.id} className="rounded border border-linha-forte/50 bg-papel px-2 py-1">
          <span className="font-mono">#{d.id}</span> · {d.acao_tipo} ·
          <span className={`ml-1 font-semibold ${corStatus(d.status)}`}>{d.status}</span>
          <div className="text-tinta-3">
            autor {d.autor} ({d.autor_perfil}) · versão {d.versao}
          </div>
          <div className="mt-0.5 text-tinta-2">{d.justificativa}</div>
        </li>
      ))}
    </ul>
  );
}

function corStatus(status: string): string {
  if (status === "APROVADA") return "text-decisao-tinta";
  if (status === "REJEITADA" || status === "REVOGADA" || status === "SUBSTITUIDA") return "text-tinta-3";
  return "text-decisao";
}

function AprovarInline({
  decisao,
  aoAprovar,
  aoRejeitar,
}: {
  decisao: Decisao;
  aoAprovar: (externa?: { aprovador?: string; evidencia?: string; data?: string }) => void;
  aoRejeitar: (motivo: string) => void;
}) {
  const [externa, setExterna] = useState({ aprovador: "", evidencia: "", data: "" });
  const [motivo, setMotivo] = useState("");

  return (
    <div className="mt-2 space-y-1">
      <details>
        <summary className="cursor-pointer text-xs text-tinta-3">Aprovação externa (opcional)</summary>
        <div className="mt-1 grid grid-cols-1 gap-1 sm:grid-cols-3">
          <input className="rounded border border-linha-forte px-1 py-0.5 text-xs"
            placeholder="Aprovador (ex.: Comercial por e-mail)"
            value={externa.aprovador} onChange={(e) => setExterna({ ...externa, aprovador: e.target.value })} />
          <input className="rounded border border-linha-forte px-1 py-0.5 text-xs"
            placeholder="Evidência (nº, link)"
            value={externa.evidencia} onChange={(e) => setExterna({ ...externa, evidencia: e.target.value })} />
          <input type="date" className="rounded border border-linha-forte px-1 py-0.5 text-xs"
            value={externa.data} onChange={(e) => setExterna({ ...externa, data: e.target.value })} />
        </div>
      </details>
      <div className="flex flex-wrap gap-1">
        <button
          onClick={() => aoAprovar(externa.aprovador ? externa : undefined)}
          className="rounded border border-decisao bg-decisao-fundo px-2 py-1 text-xs font-medium text-decisao-tinta hover:bg-decisao/20"
        >
          Confirmar aprovação
        </button>
        <input
          className="flex-1 rounded border border-linha-forte px-1 py-0.5 text-xs"
          placeholder="motivo da rejeição"
          value={motivo}
          onChange={(e) => setMotivo(e.target.value)}
        />
        <button
          disabled={!motivo}
          onClick={() => aoRejeitar(motivo)}
          className="rounded border border-linha-forte px-2 py-1 text-xs hover:bg-papel disabled:opacity-50"
        >
          Rejeitar
        </button>
      </div>
      <p className="text-[11px] text-tinta-3">
        A aprovação exige perfil compatível (R20): quem clica aqui vira o aprovador autenticado.
        {decisao.autor_perfil && (
          <> Autor atual: {decisao.autor}.</>
        )}
      </p>
    </div>
  );
}

function PropostaForm({
  caso,
  pendencia,
  acoesCompat,
  aoProposto,
}: {
  caso: Caso;
  pendencia: { id_saida: string | null; tipo: string | null };
  acoesCompat: Tratamento[];
  aoProposto: () => void;
}) {
  const [acaoTipo, setAcaoTipo] = useState(acoesCompat[0]?.tipo ?? "");
  const [justificativa, setJustificativa] = useState("");
  const [parametros, setParametros] = useState<Record<string, string>>({});
  const [escopo, setEscopo] = useState<"CASO" | "CONDICAO">("CASO");
  const [vigenciaInicio, setVigenciaInicio] = useState("");
  const [vigenciaFim, setVigenciaFim] = useState("");
  const [erro, setErro] = useState<string | null>(null);

  const acao = acoesCompat.find((a) => a.tipo === acaoTipo);

  async function enviar() {
    setErro(null);
    try {
      await api.propor({
        caso_hash: caso.caso_hash,
        escopo,
        cnpj: caso.cnpj || undefined,
        acao_tipo: acaoTipo,
        parametros: montarParametros(acao, parametros),
        justificativa,
        vigencia_inicio: escopo === "CONDICAO" ? vigenciaInicio || undefined : undefined,
        vigencia_fim: escopo === "CONDICAO" ? vigenciaFim || undefined : undefined,
      });
      aoProposto();
    } catch (e) {
      setErro((e as Error).message);
    }
  }

  if (acoesCompat.length === 0) {
    return <p className="mt-2 text-xs text-tinta-3">Nenhuma ação suportada para o tipo {pendencia.tipo}.</p>;
  }

  return (
    <div className="mt-2 space-y-2 rounded border border-linha-forte bg-papel p-2 text-xs">
      <label className="block">
        <span className="text-tinta-3">Ação</span>
        <select
          className="mt-0.5 w-full rounded border border-linha-forte px-1 py-0.5"
          value={acaoTipo}
          onChange={(e) => setAcaoTipo(e.target.value)}
        >
          {acoesCompat.map((a) => (
            <option key={a.tipo} value={a.tipo}>
              {a.tipo} · aprova: {a.aprovado_por.join("/")}
            </option>
          ))}
        </select>
        {acao && <p className="mt-0.5 text-[11px] text-tinta-3">{acao.descricao}</p>}
      </label>

      <label className="block">
        <span className="text-tinta-3">Escopo</span>
        <select
          className="mt-0.5 w-full rounded border border-linha-forte px-1 py-0.5"
          value={escopo}
          onChange={(e) => setEscopo(e.target.value as "CASO" | "CONDICAO")}
        >
          <option value="CASO">Só este caso</option>
          <option value="CONDICAO">Condição reutilizável (CNPJ/vigência)</option>
        </select>
      </label>

      {escopo === "CONDICAO" && (
        <div className="grid grid-cols-2 gap-1">
          <input type="date" placeholder="início" value={vigenciaInicio}
            onChange={(e) => setVigenciaInicio(e.target.value)}
            className="rounded border border-linha-forte px-1 py-0.5" />
          <input type="date" placeholder="fim" value={vigenciaFim}
            onChange={(e) => setVigenciaFim(e.target.value)}
            className="rounded border border-linha-forte px-1 py-0.5" />
        </div>
      )}

      {(acao?.parametros_obrigatorios ?? []).map((p) => (
        <label className="block" key={p}>
          <span className="text-tinta-3">{p}</span>
          <input
            className="mt-0.5 w-full rounded border border-linha-forte px-1 py-0.5"
            value={parametros[p] ?? ""}
            onChange={(e) => setParametros((prev) => ({ ...prev, [p]: e.target.value }))}
          />
        </label>
      ))}

      <label className="block">
        <span className="text-tinta-3">Justificativa</span>
        <textarea
          className="mt-0.5 w-full rounded border border-linha-forte px-1 py-0.5"
          rows={2}
          value={justificativa}
          onChange={(e) => setJustificativa(e.target.value)}
        />
      </label>

      {erro && <p className="text-xs text-erro">{erro}</p>}
      <button
        disabled={!justificativa.trim()}
        onClick={enviar}
        className="rounded border border-linha-forte px-2 py-1 text-xs hover:bg-folha disabled:opacity-50"
      >
        Salvar proposta
      </button>
    </div>
  );
}

function montarParametros(acao: Tratamento | undefined, raw: Record<string, string>): Record<string, unknown> {
  if (!acao) return raw;
  const out: Record<string, unknown> = {};
  for (const p of acao.parametros_obrigatorios) {
    if (p === "taxas") {
      try {
        out[p] = JSON.parse(raw[p] || "{}");
      } catch {
        out[p] = raw[p];
      }
    } else {
      out[p] = raw[p];
    }
  }
  return out;
}

function ResultadoOperacionalForm({
  caso,
  atual,
  aoAtualizar,
}: {
  caso: Caso;
  atual: { status: string; saldo_centavos: number | null; evidencia: string | null } | null;
  aoAtualizar: () => void;
}) {
  const [status, setStatus] = useState<"ABERTO" | "AGUARDANDO_RETORNO" | "PARCIAL" | "RESOLVIDO">("AGUARDANDO_RETORNO");
  const [saldoCentavos, setSaldoCentavos] = useState("");
  const [evidencia, setEvidencia] = useState("");
  const [erro, setErro] = useState<string | null>(null);

  async function enviar() {
    setErro(null);
    try {
      await api.registrarResultado(caso.caso_hash, {
        status,
        saldo_centavos: saldoCentavos ? Number(saldoCentavos) : undefined,
        evidencia: evidencia || undefined,
      });
      aoAtualizar();
      setSaldoCentavos("");
      setEvidencia("");
    } catch (e) {
      setErro((e as Error).message);
    }
  }

  return (
    <details className="mt-3">
      <summary className="cursor-pointer text-xs text-tinta-3">Resultado operacional (independente do fechamento)</summary>
      {atual && (
        <p className="mt-1 text-[11px] text-tinta-3">
          Atual: {atual.status}{" "}
          {atual.saldo_centavos != null && <>· saldo {dinheiro(atual.saldo_centavos / 100)}</>}
          {atual.evidencia && <>· evidência: {atual.evidencia}</>}
        </p>
      )}
      <div className="mt-1 grid grid-cols-1 gap-1 sm:grid-cols-3">
        <select
          value={status}
          onChange={(e) => setStatus(e.target.value as typeof status)}
          className="rounded border border-linha-forte px-1 py-0.5 text-xs"
        >
          <option>ABERTO</option>
          <option>AGUARDANDO_RETORNO</option>
          <option>PARCIAL</option>
          <option>RESOLVIDO</option>
        </select>
        <input
          placeholder="saldo em centavos (parcial)"
          value={saldoCentavos}
          onChange={(e) => setSaldoCentavos(e.target.value)}
          className="rounded border border-linha-forte px-1 py-0.5 text-xs"
        />
        <input
          placeholder="evidência (obrigatória se RESOLVIDO)"
          value={evidencia}
          onChange={(e) => setEvidencia(e.target.value)}
          className="rounded border border-linha-forte px-1 py-0.5 text-xs"
        />
      </div>
      {erro && <p className="mt-1 text-xs text-erro">{erro}</p>}
      <button
        onClick={enviar}
        className="mt-1 rounded border border-linha-forte px-2 py-1 text-xs hover:bg-folha"
      >
        Registrar resultado
      </button>
    </details>
  );
}

file.content:
export type Linha = Record<string, string | null>;

export interface Fechamento {
  competencia: string;
  execucao_id: number;
  pasta_saida: string;
  regras_versao: string;
  duracao_s: number;
  arquivos: { nome: string; bytes: number; opcional: boolean }[];
  bloqueios: Bloqueio[];
  validacoes: {
    rastro_ok: boolean;
    integridade_ok: boolean;
    problemas: string[];
    referencia: { casos_referencia_ok: number; casos_referencia_total: number } | null;
  };
  totais: Record<
    "comissao_checkout" | "comissao_remessa" | "cobrar_orbe" | "devolver_condicao" | "divergencia_remessa" | "notas",
    string
  >;
  tabelas: Record<"comissoes" | "divergencias" | "notas" | "lancamentos" | "pendencias", Linha[]>;
  casos: Record<string, Caso>;
  aplicacoes_decisoes: { caso_hash: string; decisao_id: number; escopo: string; acao_tipo: string }[];
}

export interface Caso {
  caso_hash: string;
  tipo: string;
  cnpj: string;
  ref: string;
  competencia: string;
  composicao: string[];
}

export interface Tratamento {
  tipo: string;
  descricao: string;
  aprovado_por: string[];
  altera_referencia: boolean;
  altera_calculo: boolean;
  apenas_operacional: boolean;
  parametros_obrigatorios: string[];
  tipos_pendencia: string[];
}

export interface Decisao {
  id: number;
  caso_hash: string | null;
  escopo: "CASO" | "CONDICAO";
  acao_tipo: string;
  status: "PENDENTE" | "APROVADA" | "REJEITADA" | "REVOGADA" | "SUBSTITUIDA";
  versao: number;
  justificativa: string;
  evidencias?: unknown[];
  parametros?: Record<string, unknown>;
  autor: string;
  autor_perfil: string;
  aprovador: string | null;
  aprovador_perfil: string | null;
  aprovado_em: string | null;
  aprovacao_externa?: { aprovador?: string; evidencia?: string; data?: string };
  criado_em: string;
  substitui_id: number | null;
}

export interface ResultadoOperacional {
  id: number;
  caso_hash: string;
  status: "ABERTO" | "AGUARDANDO_RETORNO" | "PARCIAL" | "RESOLVIDO";
  saldo_centavos: number | null;
  operacoes?: string[];
  evidencia: string | null;
  descricao: string | null;
  autor: string;
  timestamp: string;
}

export interface CasoDetalhe {
  decisoes: Decisao[];
  eventos: { tipo_evento: string; timestamp: string; autor: string | null; payload?: Record<string, unknown> }[];
  resultados: ResultadoOperacional[];
}

export interface Bloqueio {
  frente: string;
  faltando: string[];
  parcial: boolean;
  nao_sai: string;
  motivo_layout?: string;
}

export interface Condicao {
  id: string;
  cnpj: string;
  lojista?: string;
  taxas: Record<string, string>;
  inicio: string;
  fim: string | null;
  descricao?: string;
  fonte: string;
  aprovado_por: string;
  registrado_por?: string;
  registrado_em?: string;
}

export interface SinalAberto {
  id_saida: string;
  cnpj: string;
  lojista: string;
  linha: number;
  campo: string;
  texto: string;
  metodo: string;
}

/** Identidade do operador: usada só no header, nunca como aprovador autenticado. */
export interface Operador {
  nome: string;
  perfil: "financeiro" | "comercial" | "operador";
}

let operadorAtual: Operador = (() => {
  const salvo = typeof localStorage !== "undefined" ? localStorage.getItem("tarvo:operador") : null;
  if (salvo) try { return JSON.parse(salvo) as Operador; } catch { /* ignora */ }
  return { nome: "Fox AI", perfil: "operador" };
})();

export function definirOperador(op: Operador) {
  operadorAtual = op;
  if (typeof localStorage !== "undefined") localStorage.setItem("tarvo:operador", JSON.stringify(op));
}

export function operador(): Operador {
  return operadorAtual;
}

function headersOperador(): HeadersInit {
  return { "X-Tarvo-Usuario": operadorAtual.nome, "X-Tarvo-Perfil": operadorAtual.perfil };
}

async function pedir<T>(url: string, init?: RequestInit): Promise<T> {
  const r = await fetch(url, init);
  if (!r.ok) {
    const corpo = await r.json().catch(() => ({}));
    throw new Error(typeof corpo.detail === "string" ? corpo.detail : `Erro ${r.status} em ${url}`);
  }
  return r.json() as Promise<T>;
}

const json = (corpo: unknown, autenticado = false): RequestInit => ({
  method: "POST",
  headers: {
    "Content-Type": "application/json",
    ...(autenticado ? headersOperador() : {}),
  },
  body: JSON.stringify(corpo),
});

export const api = {
  fechamento: () => pedir<Fechamento>("/api/fechamento"),
  fechar: () => pedir<Fechamento>("/api/fechar", { method: "POST" }),
  rastro: (id: string) => pedir<{ id_saida: string; linhas: Linha[] }>(`/api/rastro/${encodeURIComponent(id)}`),
  rastroCompleto: () => pedir<{ linhas: Linha[] }>("/api/rastro"),
  lojistas: () => pedir<{ cnpj: string; lojista: string }[]>("/api/lojistas"),
  condicoes: () => pedir<{ condicoes: Condicao[]; sinais_resolvidos: Linha[] }>("/api/condicoes"),
  sinais: () => pedir<SinalAberto[]>("/api/sinais"),
  registrarCondicao: (c: Omit<Condicao, "id">) =>
    pedir<{ condicao: Condicao; fechamento: Fechamento }>("/api/condicoes", json(c)),
  resolverSinal: (s: { cnpj: string; texto: string; fonte: string; registrado_por: string }) =>
    pedir<{ fechamento: Fechamento }>("/api/sinais-resolvidos", json(s)),
  enviarArquivos: (arquivos: FileList | File[]) => {
    const form = new FormData();
    Array.from(arquivos).forEach((f) => form.append("arquivos", f));
    return pedir<Fechamento>("/api/arquivos", { method: "POST", body: form });
  },

  tratamentos: () => pedir<{ acoes: Tratamento[] }>("/api/tratamentos"),
  caso: (hash: string) => pedir<CasoDetalhe>(`/api/casos/${hash}`),
  precedentes: (hash: string) => pedir<{ precedentes: Decisao[] }>(`/api/casos/${hash}/precedentes`),
  propor: (corpo: Record<string, unknown>) =>
    pedir<Decisao>("/api/decisoes", json(corpo, true)),
  aprovar: (id: number, corpo: Record<string, unknown> = {}) =>
    pedir<{ decisao: Decisao; fechamento: Fechamento }>(`/api/decisoes/${id}/aprovar`, json(corpo, true)),
  rejeitar: (id: number, motivo: string) =>
    pedir<Decisao>(`/api/decisoes/${id}/rejeitar`, json({ motivo }, true)),
  revogar: (id: number, motivo: string) =>
    pedir<Decisao>(`/api/decisoes/${id}/revogar`, json({ motivo }, true)),
  registrarResultado: (caso_hash: string, corpo: Record<string, unknown>) =>
    pedir<{ id: number }>(`/api/casos/${caso_hash}/resultado`, json(corpo, true)),
  metricas: () => pedir<Record<string, unknown>>("/api/metricas"),
};

"""Identidade estável de pendência para o ciclo de decisão.

Um caso é "o mesmo problema" entre execuções. Não serve posição de linha, horário de
execução, nem o `id_saida` quando ele pode mudar (por exemplo, um `RM-NEG-PC-...` muda
se a Ponte reemitir o relatório). O caso é identificado por campos de negócio: tipo da
pendência, CNPJ/EC envolvido, referência de origem e competência.

Além da chave, cada caso tem uma composição (conjunto de operações/refs envolvidas,
quando a pendência é agregada). Se a composição muda entre execuções, registramos um
evento para que a decisão anterior seja reavaliada em vez de aplicada em silêncio.
"""

from __future__ import annotations

import hashlib
import re
from collections.abc import Iterable
from dataclasses import dataclass

import pandas as pd

_SO_DIGITOS = re.compile(r"\D+")


def _norm_cnpj(valor: object) -> str:
    """CNPJ só dígitos, 14 posições; devolve string vazia quando não houver."""
    s = _SO_DIGITOS.sub("", str(valor or ""))
    return s.zfill(14) if s else ""


def _norm_ref(valor: object) -> str:
    return str(valor or "").strip()


@dataclass(frozen=True)
class Caso:
    """Representação de um caso de negócio, independente da execução."""

    caso_hash: str
    tipo: str
    cnpj: str
    ref: str
    competencia: str
    composicao: tuple[str, ...]  # refs das operações envolvidas (ordem canônica)

    @property
    def composicao_hash(self) -> str:
        base = "|".join(self.composicao)
        return hashlib.sha256(base.encode("utf-8")).hexdigest()[:16]


def _hash_caso(tipo: str, cnpj: str, ref: str, competencia: str) -> str:
    base = f"{tipo}|{cnpj}|{ref}|{competencia}"
    return hashlib.sha256(base.encode("utf-8")).hexdigest()[:16]


def _composicao(rastro: pd.DataFrame, id_saida: str) -> tuple[str, ...]:
    """Refs do rastro vinculadas a um id_saida, em ordem canônica."""
    if rastro is None or rastro.empty:
        return ()
    linhas = rastro[rastro["id_saida"] == id_saida]
    if linhas.empty:
        return ()
    refs = linhas["ref_origem"].astype(str).unique().tolist()
    return tuple(sorted(refs))


def construir(pendencia: dict, rastro: pd.DataFrame, competencia: str) -> Caso:
    """Devolve o caso correspondente a uma linha de `pendencias.csv`.

    `cnpj` sai de ref_origem quando ela é CNPJ (14 dígitos). Para pendências por
    operação (ex.: `RM-NEG-PC-0926-0210`), o CNPJ fica em branco e o caso é
    identificado pelo tipo + ref + competência.
    """
    tipo = str(pendencia["tipo"])
    ref = _norm_ref(pendencia.get("ref_origem"))
    cnpj = _norm_cnpj(ref) if ref.isdigit() and len(ref) >= 11 else ""
    composicao = _composicao(rastro, str(pendencia["id_saida"]))
    return Caso(
        caso_hash=_hash_caso(tipo, cnpj, ref, competencia),
        tipo=tipo,
        cnpj=cnpj,
        ref=ref,
        competencia=competencia,
        composicao=composicao,
    )


def construir_lote(
    pendencias: pd.DataFrame, rastro: pd.DataFrame, competencia: str
) -> dict[str, Caso]:
    """Mapa `id_saida -> Caso` para todas as pendências de uma execução."""
    if pendencias is None or pendencias.empty:
        return {}
    saida: dict[str, Caso] = {}
    for linha in pendencias.to_dict("records"):
        saida[str(linha["id_saida"])] = construir(linha, rastro, competencia)
    return saida


def precedentes_semelhantes(caso: Caso, outros: Iterable[Caso]) -> list[Caso]:
    """Casos com o mesmo tipo mas identidade diferente (uso só como referência)."""
    saida = []
    for c in outros:
        if c.tipo == caso.tipo and c.caso_hash != caso.caso_hash:
            saida.append(c)
    return saida

