15	 */
16	export function FluxoDecisao({ caso, pendencia, aoAtualizar }: Props) {
17	  const [detalhe, setDetalhe] = useState<CasoDetalhe | null>(null);
18	  const [precedentes, setPrecedentes] = useState<Decisao[]>([]);
19	  const [acoes, setAcoes] = useState<Tratamento[]>([]);
20	  const [erro, setErro] = useState<string | null>(null);
21	  const [mensagem, setMensagem] = useState<string | null>(null);
22	  const [abrirForm, setAbrirForm] = useState(false);
23	
24	  async function recarregar() {
25	    const [d, p, t] = await Promise.all([
26	      api.caso(caso.caso_hash),
27	      api.precedentes(caso.caso_hash).catch(() => ({ precedentes: [] })),
28	      api.tratamentos(),
29	    ]);
30	    setDetalhe(d);
31	    setPrecedentes(p.precedentes);
32	    setAcoes(t.acoes);
33	  }
34	
35	  useEffect(() => {
36	    recarregar().catch((e) => setErro((e as Error).message));
37	    // eslint-disable-next-line react-hooks/exhaustive-deps
38	  }, [caso.caso_hash]);
39	
40	  const acoesCompat = useMemo(() => {
41	    const tipo = pendencia.tipo ?? "";
42	    return acoes.filter(
43	      (a) => a.tipos_pendencia.includes(tipo) || (a.apenas_operacional && a.tipos_pendencia.length === 0)
44	    );
45	  }, [acoes, pendencia.tipo]);
46	
47	  const pendente = detalhe?.decisoes.find((d) => d.status === "PENDENTE") ?? null;
48	  const aprovada = detalhe?.decisoes.find((d) => d.status === "APROVADA") ?? null;
49	  const resultado = detalhe?.resultados[0] ?? null;
50	
51	  async function tratar<T>(acao: () => Promise<T>, msg: string) {
52	    try {
53	      await acao();
54	      setMensagem(msg);
55	      await recarregar();
56	      aoAtualizar();
57	    } catch (e) {
58	      setErro((e as Error).message);
59	    }
60	  }
61	
62	  return (
63	    <div className="mt-4 rounded-md border border-linha bg-folha/50 p-3 text-sm">
64	      <h3 className="mb-2 text-xs font-semibold uppercase tracking-wider text-tinta-3">Ciclo de decisão</h3>
65	      {erro && <p className="mb-2 text-xs text-erro">{erro}</p>}
66	      {mensagem && <p className="mb-2 text-xs text-tinta-2">{mensagem}</p>}
67	
68	      <HistoricoDecisoes decisoes={detalhe?.decisoes ?? []} />
69	
70	      {aprovada && (
71	        <div className="mt-2 rounded border border-decisao/50 bg-decisao-fundo p-2 text-xs">
72	          <p>
73	            <strong>Tratamento aplicado:</strong> {aprovada.acao_tipo} ·
74	            aprovado por <strong>{aprovada.aprovador}</strong>
75	            {aprovada.aprovacao_externa?.aprovador && (
76	              <> (externamente: {aprovada.aprovacao_externa.aprovador})</>
77	            )}
78	          </p>
79	          <button
80	            onClick={() =>
81	              tratar(() => api.revogar(aprovada.id, "revogada pelo painel"), "Decisão revogada.")
82	            }
83	            className="mt-1 rounded border border-linha-forte px-2 py-0.5 text-xs hover:bg-papel"
84	          >
85	            Revogar
86	          </button>
87	        </div>
88	      )}
89	
90	      {pendente && (
91	        <div className="mt-2 rounded border border-linha-forte bg-papel p-2 text-xs">
92	          <p>
93	            Proposta <strong>#{pendente.id}</strong> ({pendente.acao_tipo}) aguardando aprovação.
94	            Autor: {pendente.autor}.
95	          </p>
96	          <AprovarInline
97	            decisao={pendente}
98	            aoAprovar={(externa) =>
99	              tratar(
100	                () => api.aprovar(pendente.id, externa ? { aprovacao_externa: externa } : {}),
101	                "Decisão aprovada e aplicada."
102	              )
103	            }
104	            aoRejeitar={(motivo) => tratar(() => api.rejeitar(pendente.id, motivo), "Proposta rejeitada.")}
105	          />
106	        </div>
107	      )}
108	
109	      {!pendente && !aprovada && (
110	        <button
111	          onClick={() => setAbrirForm((v) => !v)}
112	          className="mt-2 rounded border border-linha-forte px-2 py-1 text-xs hover:bg-papel"
113	        >
114	          {abrirForm ? "Fechar formulário" : "Registrar proposta de tratamento"}
115	        </button>
116	      )}
117	
118	      {abrirForm && !pendente && !aprovada && (
119	        <PropostaForm
120	          caso={caso}
121	          pendencia={pendencia}
122	          acoesCompat={acoesCompat}
123	          aoProposto={() => {
124	            setAbrirForm(false);
125	            tratar(() => Promise.resolve(null), "Proposta registrada. Falta aprovação.");
126	          }}
127	        />
128	      )}
129	
130	      <ResultadoOperacionalForm caso={caso} atual={resultado} aoAtualizar={() => tratar(() => Promise.resolve(null), "Resultado atualizado.")} />
131	
132	      {precedentes.length > 0 && (
133	        <details className="mt-3">
134	          <summary className="cursor-pointer text-xs text-tinta-3 hover:text-tinta">
135	            Precedentes (não autorizam, só referência) · {precedentes.length}
136	          </summary>
137	          <ul className="mt-1 space-y-1 text-xs">
138	            {precedentes.map((p) => (
139	              <li key={p.id} className="rounded border border-linha-forte/60 bg-papel px-2 py-1">
140	                <span className="font-mono">{p.acao_tipo}</span> · {p.justificativa}
141	                <span className="ml-2 text-tinta-3">({p.status})</span>
142	              </li>
143	            ))}
144	          </ul>
145	        </details>
146	      )}
147	    </div>
148	  );
149	}
150	
151	function HistoricoDecisoes({ decisoes }: { decisoes: Decisao[] }) {
152	  if (!decisoes.length) return <p className="text-xs text-tinta-3">Nenhuma decisão registrada ainda.</p>;
153	  return (
154	    <ul className="space-y-1 text-xs">
155	      {decisoes.map((d) => (
156	        <li key={d.id} className="rounded border border-linha-forte/50 bg-papel px-2 py-1">
157	          <span className="font-mono">#{d.id}</span> · {d.acao_tipo} ·
158	          <span className={`ml-1 font-semibold ${corStatus(d.status)}`}>{d.status}</span>
159	          <div className="text-tinta-3">
160	            autor {d.autor} ({d.autor_perfil}) · versão {d.versao}
161	          </div>
162	          <div className="mt-0.5 text-tinta-2">{d.justificativa}</div>
163	        </li>
164	      ))}
165	    </ul>
166	  );
167	}
168	
169	function corStatus(status: string): string {
170	  if (status === "APROVADA") return "text-decisao-tinta";
171	  if (status === "REJEITADA" || status === "REVOGADA" || status === "SUBSTITUIDA") return "text-tinta-3";
172	  return "text-decisao";
173	}
174	
175	function AprovarInline({
176	  decisao,
177	  aoAprovar,
178	  aoRejeitar,
179	}: {
180	  decisao: Decisao;
181	  aoAprovar: (externa?: { aprovador?: string; evidencia?: string; data?: string }) => void;
182	  aoRejeitar: (motivo: string) => void;
183	}) {
184	  const [externa, setExterna] = useState({ aprovador: "", evidencia: "", data: "" });
185	  const [motivo, setMotivo] = useState("");
186	
187	  return (
188	    <div className="mt-2 space-y-1">
189	      <details>
190	        <summary className="cursor-pointer text-xs text-tinta-3">Aprovação externa (opcional)</summary>
191	        <div className="mt-1 grid grid-cols-1 gap-1 sm:grid-cols-3">
192	          <input className="rounded border border-linha-forte px-1 py-0.5 text-xs"
193	            placeholder="Aprovador (ex.: Comercial por e-mail)"
194	            value={externa.aprovador} onChange={(e) => setExterna({ ...externa, aprovador: e.target.value })} />
195	          <input className="rounded border border-linha-forte px-1 py-0.5 text-xs"
196	            placeholder="Evidência (nº, link)"
197	            value={externa.evidencia} onChange={(e) => setExterna({ ...externa, evidencia: e.target.value })} />
198	          <input type="date" className="rounded border border-linha-forte px-1 py-0.5 text-xs"
199	            value={externa.data} onChange={(e) => setExterna({ ...externa, data: e.target.value })} />
200	        </div>
201	      </details>
202	      <div className="flex flex-wrap gap-1">
203	        <button
204	          onClick={() => aoAprovar(externa.aprovador ? externa : undefined)}
205	          className="rounded border border-decisao bg-decisao-fundo px-2 py-1 text-xs font-medium text-decisao-tinta hover:bg-decisao/20"
206	        >
207	          Confirmar aprovação
208	        </button>
209	        <input
210	          className="flex-1 rounded border border-linha-forte px-1 py-0.5 text-xs"
211	          placeholder="motivo da rejeição"
212	          value={motivo}
213	          onChange={(e) => setMotivo(e.target.value)}
214	        />
215	        <button
216	          disabled={!motivo}
217	          onClick={() => aoRejeitar(motivo)}
218	          className="rounded border border-linha-forte px-2 py-1 text-xs hover:bg-papel disabled:opacity-50"
219	        >
220	          Rejeitar
221	        </button>
222	      </div>
223	      <p className="text-[11px] text-tinta-3">
224	        A aprovação exige perfil compatível (R20): quem clica aqui vira o aprovador autenticado.
225	        {decisao.autor_perfil && (
226	          <> Autor atual: {decisao.autor}.</>
227	        )}
228	      </p>
229	    </div>
230	  );
231	}
232	
233	function PropostaForm({
234	  caso,
235	  pendencia,
236	  acoesCompat,
237	  aoProposto,
238	}: {
239	  caso: Caso;
240	  pendencia: { id_saida: string | null; tipo: string | null };
241	  acoesCompat: Tratamento[];
242	  aoProposto: () => void;
243	}) {
244	  const [acaoTipo, setAcaoTipo] = useState(acoesCompat[0]?.tipo ?? "");
245	  const [justificativa, setJustificativa] = useState("");
246	  const [parametros, setParametros] = useState<Record<string, string>>({});
247	  const [escopo, setEscopo] = useState<"CASO" | "CONDICAO">("CASO");
248	  const [vigenciaInicio, setVigenciaInicio] = useState("");
249	  const [vigenciaFim, setVigenciaFim] = useState("");
250	  const [erro, setErro] = useState<string | null>(null);
251	
252	  const acao = acoesCompat.find((a) => a.tipo === acaoTipo);
253	
254	  async function enviar() {
255	    setErro(null);
256	    try {
257	      await api.propor({
258	        caso_hash: caso.caso_hash,
259	        escopo,
260	        cnpj: caso.cnpj || undefined,
261	        acao_tipo: acaoTipo,
262	        parametros: montarParametros(acao, parametros),
263	        justificativa,
264	        vigencia_inicio: escopo === "CONDICAO" ? vigenciaInicio || undefined : undefined,
265	        vigencia_fim: escopo === "CONDICAO" ? vigenciaFim || undefined : undefined,
266	      });
267	      aoProposto();
268	    } catch (e) {
269	      setErro((e as Error).message);
270	    }
271	  }
272	
273	  if (acoesCompat.length === 0) {
274	    return <p className="mt-2 text-xs text-tinta-3">Nenhuma ação suportada para o tipo {pendencia.tipo}.</p>;
275	  }
276	
277	  return (
278	    <div className="mt-2 space-y-2 rounded border border-linha-forte bg-papel p-2 text-xs">
279	      <label className="block">
280	        <span className="text-tinta-3">Ação</span>
281	        <select
282	          className="mt-0.5 w-full rounded border border-linha-forte px-1 py-0.5"
283	          value={acaoTipo}
284	          onChange={(e) => setAcaoTipo(e.target.value)}
285	        >
286	          {acoesCompat.map((a) => (
287	            <option key={a.tipo} value={a.tipo}>
288	              {a.tipo} · aprova: {a.aprovado_por.join("/")}
289	            </option>
290	          ))}
291	        </select>
292	        {acao && <p className="mt-0.5 text-[11px] text-tinta-3">{acao.descricao}</p>}
293	      </label>
294	
295	      <label className="block">
296	        <span className="text-tinta-3">Escopo</span>
297	        <select
298	          className="mt-0.5 w-full rounded border border-linha-forte px-1 py-0.5"
299	          value={escopo}
300	          onChange={(e) => setEscopo(e.target.value as "CASO" | "CONDICAO")}
301	        >
302	          <option value="CASO">Só este caso</option>
303	          <option value="CONDICAO">Condição reutilizável (CNPJ/vigência)</option>
304	        </select>
305	      </label>
306	
307	      {escopo === "CONDICAO" && (
308	        <div className="grid grid-cols-2 gap-1">
309	          <input type="date" placeholder="início" value={vigenciaInicio}
310	            onChange={(e) => setVigenciaInicio(e.target.value)}
311	            className="rounded border border-linha-forte px-1 py-0.5" />
312	          <input type="date" placeholder="fim" value={vigenciaFim}
313	            onChange={(e) => setVigenciaFim(e.target.value)}
314	            className="rounded border border-linha-forte px-1 py-0.5" />
315	        </div>
316	      )}
317	
318	      {(acao?.parametros_obrigatorios ?? []).map((p) => (
319	        <label className="block" key={p}>
320	          <span className="text-tinta-3">{p}</span>
321	          <input
322	            className="mt-0.5 w-full rounded border border-linha-forte px-1 py-0.5"
323	            value={parametros[p] ?? ""}
324	            onChange={(e) => setParametros((prev) => ({ ...prev, [p]: e.target.value }))}
325	          />
326	        </label>
327	      ))}
328	
329	      <label className="block">
330	        <span className="text-tinta-3">Justificativa</span>
331	        <textarea
332	          className="mt-0.5 w-full rounded border border-linha-forte px-1 py-0.5"
333	          rows={2}
334	          value={justificativa}
335	          onChange={(e) => setJustificativa(e.target.value)}
336	        />
337	      </label>
338	
339	      {erro && <p className="text-xs text-erro">{erro}</p>}
340	      <button
341	        disabled={!justificativa.trim()}
342	        onClick={enviar}
343	        className="rounded border border-linha-forte px-2 py-1 text-xs hover:bg-folha disabled:opacity-50"
344	      >
345	        Salvar proposta
346	      </button>
347	    </div>
348	  );
349	}
350	
351	function montarParametros(acao: Tratamento | undefined, raw: Record<string, string>): Record<string, unknown> {
352	  if (!acao) return raw;
353	  const out: Record<string, unknown> = {};
354	  for (const p of acao.parametros_obrigatorios) {
355	    if (p === "taxas") {
356	      try {
357	        out[p] = JSON.parse(raw[p] || "{}");
358	      } catch {
359	        out[p] = raw[p];
360	      }
361	    } else {
362	      out[p] = raw[p];
363	    }
364	  }
365	  return out;
366	}
367	
368	function ResultadoOperacionalForm({
369	  caso,
370	  atual,
371	  aoAtualizar,
372	}: {
373	  caso: Caso;
374	  atual: { status: string; saldo_centavos: number | null; evidencia: string | null } | null;
375	  aoAtualizar: () => void;
376	}) {
377	  const [status, setStatus] = useState<"ABERTO" | "AGUARDANDO_RETORNO" | "PARCIAL" | "RESOLVIDO">("AGUARDANDO_RETORNO");
378	  const [saldoCentavos, setSaldoCentavos] = useState("");
379	  const [evidencia, setEvidencia] = useState("");
380	  const [erro, setErro] = useState<string | null>(null);
381	
382	  async function enviar() {
383	    setErro(null);
384	    try {
385	      await api.registrarResultado(caso.caso_hash, {
386	        status,
387	        saldo_centavos: saldoCentavos ? Number(saldoCentavos) : undefined,
388	        evidencia: evidencia || undefined,
389	      });
390	      aoAtualizar();
391	      setSaldoCentavos("");
392	      setEvidencia("");
393	    } catch (e) {
394	      setErro((e as Error).message);
395	    }
396	  }
397	
398	  return (
399	    <details className="mt-3">
400	      <summary className="cursor-pointer text-xs text-tinta-3">Resultado operacional (independente do fechamento)</summary>
401	      {atual && (
402	        <p className="mt-1 text-[11px] text-tinta-3">
403	          Atual: {atual.status}{" "}
404	          {atual.saldo_centavos != null && <>· saldo {dinheiro(atual.saldo_centavos / 100)}</>}
405	          {atual.evidencia && <>· evidência: {atual.evidencia}</>}
406	        </p>
407	      )}
408	      <div className="mt-1 grid grid-cols-1 gap-1 sm:grid-cols-3">
409	        <select
410	          value={status}
411	          onChange={(e) => setStatus(e.target.value as typeof status)}
412	          className="rounded border border-linha-forte px-1 py-0.5 text-xs"
413	        >
414	          <option>ABERTO</option>
415	          <option>AGUARDANDO_RETORNO</option>
416	          <option>PARCIAL</option>
417	          <option>RESOLVIDO</option>
418	        </select>
419	        <input
420	          placeholder="saldo em centavos (parcial)"
421	          value={saldoCentavos}
422	          onChange={(e) => setSaldoCentavos(e.target.value)}
423	          className="rounded border border-linha-forte px-1 py-0.5 text-xs"
424	        />
425	        <input
426	          placeholder="evidência (obrigatória se RESOLVIDO)"
427	          value={evidencia}
428	          onChange={(e) => setEvidencia(e.target.value)}
429	          className="rounded border border-linha-forte px-1 py-0.5 text-xs"
430	        />
431	      </div>
432	      {erro && <p className="mt-1 text-xs text-erro">{erro}</p>}
433	      <button
434	        onClick={enviar}
435	        className="mt-1 rounded border border-linha-forte px-2 py-1 text-xs hover:bg-folha"
436	      >
437	        Registrar resultado
438	      </button>
439	    </details>
440	  );
441	}
