5	import { Condicoes } from "./components/Condicoes";
6	import { Pendencias } from "./components/Pendencias";
7	import { Rastro, type AlvoRastro } from "./components/Rastro";
8	import { Arquivos } from "./components/Upload";
9	import { Divergencias, Lancamentos, Numeros, Rastro as RastroTabela } from "./components/Tabelas";
10	import { RastroContext } from "./components/Valor";
11	import { ARQUIVO, FRENTE } from "./format";
12	
13	type Tela = "arquivos" | "pendencias" | "numeros" | "divergencias" | "lancamentos" | "rastro" | "condicoes";
14	
15	export default function App() {
16	  const [f, setF] = useState<Fechamento | null>(null);
17	  const [sinais, setSinais] = useState<SinalAberto[]>([]);
18	  const [erro, setErro] = useState<string | null>(null);
19	  const [ocupado, setOcupado] = useState<string | null>("Carregando o fechamento…");
20	  const [tela, setTela] = useState<Tela>("arquivos");
21	  const [alvo, setAlvo] = useState<AlvoRastro | null>(null);
22	  const [aviso, setAviso] = useState<string | null>(null);
23	  const [sinalForm, setSinalForm] = useState<SinalAberto | null>(null);
24	
25	  const aplicar = useCallback(async (novo: Fechamento) => {
26	    setF(novo);
27	    setSinais(await api.sinais().catch(() => []));
28	  }, []);
29	
30	  const executar = useCallback(
31	    async (rotulo: string, acao: () => Promise<Fechamento>) => {
32	      setOcupado(rotulo);
33	      setErro(null);
