58	    ["pendencias", "Pendências", pend.length],
59	    ["numeros", "Comissões e notas", null],
60	    ["divergencias", "Divergências", f?.tabelas.divergencias.length ?? null],
61	    ["lancamentos", "Lançamentos", f?.tabelas.lancamentos.length ?? null],
62	    ["rastro", "Rastro", null],
63	    ["condicoes", "Condições comerciais", null],
64	  ];
65	
66	  return (
67	    <MotionConfig reducedMotion="user">
68	      <RastroContext.Provider value={setAlvo}>
69	        <div className="min-h-screen overflow-x-hidden">
70	          <header className="sticky top-0 z-20 border-b border-linha bg-papel/95 backdrop-blur-sm">
71	            <div className="mx-auto flex max-w-[1400px] items-center px-6 py-4">
72	              <h1 className="text-3xl font-bold tracking-tight">Tarvo</h1>
73	            </div>
74	          </header>
